import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = readFileSync(join(root, "node_modules/htmx.org/dist/htmx.min.js"), "utf8");
const target = join(root, "src/admin/static/htmx.generated.ts");

const banner =
  "// Generated by `pnpm vendor:htmx` from the pinned htmx.org package. Do not edit.\n";
writeFileSync(target, `${banner}export default ${JSON.stringify(source)};\n`);
console.log(`wrote ${target} (${source.length} bytes of htmx.min.js)`);
